// Generated by vibelang from src/ProviderConformance/Violation.ts; the migrate flow writes it again with each batch.
/**
 * Defines one way a provider misses the contract.
 *
 * @since 0.1.0
 */
/**
 * Renders violations as one message.
 *
 * @category formatting
 * @since 0.1.0
 */
export const format = (violations) => violations.length === 0
    ? "provider conforms"
    : violations
        .map((violation) => `${violation.check}: expected ${violation.expected}, got ${violation.actual}`)
        .join("\n");
